const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,today=dayKey(new Date());
const seed={name:'有序',user:'同学',avatar:'',dark:false,tasks:[{id:'t1',title:'梳理文献综述的研究框架',group:'科研',date:today,time:'09:00',duration:90,done:false},{id:'t2',title:'完成高级统计学第三章习题',group:'课程',date:today,time:'14:00',duration:60,done:false},{id:'t3',title:'阅读 20 页《深度工作》',group:'课外学习',date:today,time:'20:30',duration:30,done:false},{id:'t4',title:'整理本周组会笔记',group:'科研',date:today,time:'',duration:30,done:true}],habits:{},ideas:[{id:'i1',title:'用可视化的方式整理论文之间的关系',content:'把研究问题、方法和结论联系起来，或许能更快找到值得深入的方向。',tag:'科研灵感'},{id:'i2',title:'每周给自己留一个没有安排的下午',content:'散步、看展，或者只是坐一会儿。留出空间，让新的想法发生。',tag:'生活随想'}],money:[{id:'m1',title:'午餐',amount:25,kind:'支出',category:'餐饮',date:today},{id:'m2',title:'研究生助研补贴',amount:1200,kind:'收入',category:'学习',date:today},{id:'m3',title:'书籍 · 研究方法',amount:68,kind:'支出',category:'学习',date:today}],workouts:[],notes:[{id:'n1',title:'高级统计学',content:'第三章：参数估计与假设检验\n本周重点：理解置信区间的含义，完成课后习题。',group:'课程',minutes:0},{id:'n2',title:'文献综述与研究设计',content:'整理研究问题，建立文献阅读清单。',group:'科研',minutes:0},{id:'n3',title:'英语阅读计划',content:'每天读一篇长文，记录值得积累的表达。',group:'课外学习',minutes:0}],goals:[{id:'g1',title:'完成第一篇论文初稿',period:'本学期',progress:35},{id:'g2',title:'建立稳定的运动习惯',period:'未来 3 个月',progress:20}],reviews:[]};
let state;try{state=JSON.parse(localStorage.getItem('youxu-prototype-v1'))||structuredClone(seed)}catch{state=structuredClone(seed)}
let page='today',filter='全部',selectedDate=today,formType='task',editing=null;const nav=[['today','◷','今天'],['plan','▦','计划'],['learn','▤','学习'],['finance','◈','财务'],['exercise','↗','运动与习惯'],['ideas','◇','灵感'],['goals','◎','目标'],['review','↺','复盘']];
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function save(){try{localStorage.setItem('youxu-prototype-v1',JSON.stringify(state));return true}catch{toast('本机保存失败，请导出备份');return false}}
const id=()=>crypto.randomUUID();const tasksFor=d=>state.tasks.filter(t=>t.date===d);const completed=()=>tasksFor(today).filter(t=>t.done).length;const sum=(arr,key)=>arr.reduce((n,x)=>n+Number(x[key]||0),0);
function avatar(){return state.avatar?`<img class="avatar" src="${esc(state.avatar)}" alt="头像">`:`<span class="avatar">${esc(state.user.slice(0,1))}</span>`}
function render(){document.body.classList.toggle('dark',state.dark);document.title=`${state.name} · 个人工作台`;$('#sidebar').innerHTML=`<div class="brand"><span class="logo">≋</span><div class="brand-text">${esc(state.name)}<small>PERSONAL SPACE</small></div></div><div class="nav-label">我的工作台</div>${nav.map(([k,i,n])=>`<button class="nav-item ${page===k?'active':''}" data-page="${k}"><span class="icon">${i}</span><span class="nav-text">${n}</span>${k==='today'?`<span class="count">${tasksFor(today).filter(t=>!t.done).length}</span>`:''}</button>`).join('')}<div class="sidebar-bottom"><button class="nav-item ${page==='settings'?'active':''}" data-page="settings"><span class="icon">⚙</span><span class="nav-text">偏好设置</span></button><div class="profile">${avatar()}<div class="profile-text"><div style="font-size:14px">${esc(state.user)}</div><small>我的个人空间</small></div></div></div>`;$('#breadcrumb').textContent=`我的空间 / ${nav.find(x=>x[0]===page)?.[2]||({settings:'偏好设置',explore:'探索'}[page])}`;$('#mobile').innerHTML=[['today','◷','今天'],['plan','▦','计划'],['new','⊕','记录'],['explore','◈','探索'],['settings','○','我的']].map(([k,i,n])=>`<button ${k==='new'?'data-action="new"':`data-page="${k}"`} class="${page===k?'active':''}"><span>${i}</span>${n}</button>`).join('');$('#main').innerHTML=({today:todayView,plan:planView,learn:learnView,finance:financeView,exercise:exerciseView,ideas:ideasView,goals:goalsView,review:reviewView,settings:settingsView,explore:exploreView}[page])();}
function heading(k,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function stat(label,value,unit,note,icon){return `<div class="stat"><div class="stat-label">${label}<span>${icon}</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note">${note}</div></div>`}
function card(title,body,action='',cls=''){return `<section class="card ${cls}"><div class="card-head"><h2>${title}</h2>${action}</div><div class="card-body">${body}</div></section>`}
function taskRows(arr){return arr.length?arr.map(t=>`<div class="task ${t.done?'done':''}"><button class="check ${t.done?'done':''}" data-task="${t.id}" aria-label="${t.done?'取消完成':'完成'} ${esc(t.title)}">${t.done?'✓':''}</button><div class="task-content"><div class="task-title">${esc(t.title)}</div><div class="task-meta"><span class="tag ${t.group==='课程'?'purple':t.group==='生活'?'green':''}">${esc(t.group)}</span><span>${t.duration} 分钟</span>${t.time?`<span>${t.time}</span>`:''}</div></div><button class="quiet" data-edit-task="${t.id}" aria-label="编辑任务">···</button></div>`).join(''):'<div class="empty">这一天还没有任务，给重要的事留一段时间吧。</div>'}
function habitsView(){return [['read','▤','阅读与学习','每天一点积累'],['move','↗','运动 30 分钟','与运动记录自动关联'],['reflect','☾','日终复盘','给今天画上句号']].map(([k,i,n,d])=>{const checked=habitDone(k);return `<div class="habit"><span class="habit-icon">${i}</span><div class="habit-name">${n}<small>${d}</small></div><button data-habit="${k}" class="${checked?'checked':''}">${checked?'✓ 已完成':'打卡'}</button></div>`}).join('')}
function habitDone(k){return !!state.habits[today+':'+k]||(k==='move'&&sum(state.workouts.filter(w=>w.date===today),'minutes')>=30)||(k==='reflect'&&state.reviews.some(r=>r.date===today))}
function goalRows(){return state.goals.slice(0,2).map(g=>`<div class="goal"><div class="goal-top"><span>${esc(g.title)}</span><span class="muted">${g.progress}%</span></div><div class="progress"><i style="width:${g.progress}%"></i></div><span class="muted" style="font-size:12px">${esc(g.period)} · 手动进度</span></div>`).join('')}
function todayView(){let ts=tasksFor(today),spend=sum(state.money.filter(m=>m.date===today&&m.kind==='支出'),'amount');return heading('MAKE ROOM FOR WHAT MATTERS',`你好，${esc(state.user)} <span style="font-weight:400">☀</span>`,'从最重要的一件事开始，按自己的节奏前进。',`<div class="date-pill">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</div>`)+`<div class="summary">${stat('今日任务',`${completed()} <span style="color:#b0b8c7;font-size:19px">/ ${ts.length}</span>`,'项','专注于小步向前','◷')}${stat('学习记录',sum(state.notes.filter(n=>n.date===today),'minutes'),'分钟','实际记录的学习时间','▤')}${stat('今日支出','¥ '+spend.toFixed(2),'','每一笔，都心中有数','◈')}${stat('习惯打卡',['read','move','reflect'].filter(habitDone).length,'/ 3','让坚持慢慢发生','◎')}</div><div class="dashboard"><div class="stack">${card('今日重点',taskRows(ts.filter(t=>!t.done).slice(0,3))+`<button class="small-add" data-action="new">＋ 添加一件重要的事</button>`,`<span class="tag">最多 3 件</span>`)}${card('今天的待办',taskRows(ts),`<button class="quiet" data-page="plan">查看计划 ↗</button>`)}${card('正在靠近的目标',goalRows(),`<button class="quiet" data-page="goals">全部 ↗</button>`)}</div><div class="stack">${card('时间安排',timeline(ts),`<span class="muted">今天</span>`)}${card('每日习惯',habitsView(),`<span class="muted">${['read','move','reflect'].filter(habitDone).length}/3</span>`)}${card('给今天留几句话',`<p>记录一个收获，放下还没做完的事。<br>明天，也会有新的开始。</p><button data-action="review">写下今日复盘 ↗</button>`,'','review-card')}</div></div>`}
function timeline(ts){const a=ts.filter(t=>t.time).sort((a,b)=>a.time.localeCompare(b.time));return a.length?`<div class="timeline">${a.map((t,i)=>`<div class="time-row"><span class="time-label">${t.time}</span><div class="event ${['','purple','green'][i%3]}">${esc(t.title)}<small>${esc(t.group)} · ${t.duration} 分钟 ${t.done?'· 已完成':''}</small></div></div>`).join('')}</div>`:'<div class="empty">暂未安排时间</div>'}
function planView(){let base=new Date(selectedDate+'T12:00:00'),offset=(base.getDay()+6)%7;return heading('PLAN WITH INTENTION','把时间留给重要的事','先安排，再行动。任务与今日页保持一致。',`<button data-action="new">＋ 新建任务</button>`)+`<div class="tabs"><button data-shift="-7">← 上周</button><button data-shift="0">回到今天</button><button data-shift="7">下周 →</button></div><div class="week">${Array.from({length:7},(_,i)=>{let d=new Date(base);d.setDate(base.getDate()-offset+i);let k=dayKey(d);return `<button class="day ${k===selectedDate?'active':''}" data-date="${k}"><small>${['一','二','三','四','五','六','日'][i]}</small>${d.getMonth()+1}/${d.getDate()}</button>`}).join('')}</div><div class="dashboard"><div>${card(selectedDate+' · 任务',taskRows(tasksFor(selectedDate)))}</div><div>${card('当日时间安排',timeline(tasksFor(selectedDate)))}</div></div>`}
function tabs(items){return `<div class="tabs">${items.map(t=>`<button data-filter="${t}" class="${filter===t?'active':''}">${t}</button>`).join('')}</div>`}
function learnView(){let arr=state.notes.filter(n=>filter==='全部'||n.group===filter);return heading('LEARN & DISCOVER','学习，是一场长期积累','课程、科研与好奇心，都有自己的位置。',`<button class="primary" data-action="note">＋ 学习记录</button>`)+tabs(['全部','课程','科研','课外学习'])+`<div class="grid">${arr.map(n=>`<section class="card"><div class="card-top"><span class="tag ${n.group==='课程'?'purple':''}">${esc(n.group)}</span><span class="muted">▤</span></div><h3>${esc(n.title)}</h3><p class="notes-text">${esc(n.content)}</p><div class="muted">${n.minutes?`学习 ${n.minutes} 分钟`:'学习空间 · 示例内容'}</div><div style="margin-top:20px"><button data-edit-note="${n.id}">打开记录 ↗</button></div></section>`).join('')}</div>`}
function financeView(){let month=today.slice(0,7),a=state.money.filter(m=>m.date.startsWith(month)),expense=sum(a.filter(x=>x.kind==='支出'),'amount'),income=sum(a.filter(x=>x.kind==='收入'),'amount');return heading('MONEY, WITH CLARITY','每一笔，都有去处','从记下一笔收支开始，了解自己的生活。',`<button class="primary" data-action="money">＋ 记一笔</button>`)+`<div class="summary">${stat('本月收入','¥ '+income.toFixed(2),'',month,'↙')}${stat('本月支出','¥ '+expense.toFixed(2),'','仅统计支出','↗')}${stat('本月结余','¥ '+(income-expense).toFixed(2),'','收入减去支出','◈')}${stat('本月记录',a.length,'笔','当前为本机示例账本','▤')}</div>`+card('收支记录',state.money.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<div class="record-row"><span class="habit-icon">${m.kind==='收入'?'↙':'↗'}</span><div class="grow">${esc(m.title)}<p>${m.date} · ${esc(m.category)}</p></div><span style="color:${m.kind==='收入'?'#429779':'inherit'}">${m.kind==='收入'?'+':'−'} ¥ ${Number(m.amount).toFixed(2)}</span><button class="quiet" data-delete="money:${m.id}" aria-label="删除记录">×</button></div>`).join(''))}
function exerciseView(){return heading('MOVE & FEEL GOOD','让身体，也跟上节奏','不必每次都突破，出现本身就是进步。',`<button class="primary" data-action="workout">＋ 记录运动</button>`)+`<div class="dashboard"><div>${card('运动记录',state.workouts.length?state.workouts.map(w=>`<div class="record-row"><span class="habit-icon">↗</span><div class="grow">${esc(w.title)}<p>${w.date} · ${w.minutes} 分钟 ${w.distance?'· '+w.distance+' 公里':''}</p></div><button class="quiet" data-delete="workouts:${w.id}" aria-label="删除运动">×</button></div>`).join(''):'<div class="empty">还没有运动记录。散步、跑步或一次训练，都值得记下。</div>')}</div><div>${card('今日习惯',habitsView())}<p class="muted">今日运动累计满 30 分钟，自动完成运动打卡。</p></div></div>`}
function ideasView(){return heading('A PLACE FOR POSSIBILITY','先记下来，让想法生长','不急着实现，每一个念头都有自己的时机。',`<button class="primary" data-action="idea">＋ 记下灵感</button>`)+`<div class="grid">${state.ideas.map(n=>`<section class="card"><div class="card-top"><span class="tag orange">${esc(n.tag||'随手记')}</span><button class="quiet" data-delete="ideas:${n.id}" aria-label="删除灵感">×</button></div><h3>${esc(n.title)}</h3><p class="notes-text">${esc(n.content)}</p><button data-convert="${n.id}" ${n.taskId?'disabled':''}>${n.taskId?'✓ 已关联任务':'转为今日任务 ↗'}</button></section>`).join('')}</div>`}
function goalsView(){return heading('THE BIGGER PICTURE','慢慢走，也在靠近','把远处的方向，变成眼前可以迈出的一步。',`<button class="primary" data-action="goal">＋ 新建目标</button>`)+`<div class="grid">${state.goals.map(g=>`<section class="card"><div class="card-top"><span class="tag">${esc(g.period)}</span><span class="muted">◎</span></div><h3>${esc(g.title)}</h3><div class="progress"><i style="width:${g.progress}%"></i></div><p>${g.progress}% · 手动更新进度</p><button data-edit-goal="${g.id}">更新目标 ↗</button></section>`).join('')}</div>`}
function reviewView(){return heading('PAUSE & REFLECT','回头看看，才能继续向前','记录收获、遇到的阻碍，以及下一步的小调整。',`<button class="primary" data-action="review">＋ 写复盘</button>`)+`<div class="grid">${state.reviews.length?state.reviews.map(r=>`<section class="card"><span class="tag">${r.date}</span><h3 style="margin-top:18px">${esc(r.title)}</h3><p class="notes-text">${esc(r.content)}</p><button class="quiet" data-delete="reviews:${r.id}">删除</button></section>`).join(''):`<section class="card"><h3>今天，有什么值得记住？</h3><p>一个小小的进展，一次新的发现，或是一件想调整的事。</p><button data-action="review">开始第一次复盘 ↗</button></section>`}</div>`}
function exploreView(){return heading('YOUR SPACE','探索你的工作台','学习、生活与未来，在这里相遇。')+`<div class="grid">${nav.slice(2).map(([k,i,n])=>`<button class="card" style="text-align:left" data-page="${k}"><span class="icon">${i}</span><h3 style="margin:15px 0 0">${n} ↗</h3></button>`).join('')}</div>`}
function settingsView(){return heading('MAKE IT YOURS','这是你的空间','用熟悉的名字和喜欢的方式，开始每一天。')+`<div class="settings-grid"><section class="card"><div class="setting-line"><div class="profile" style="border:0;padding:0">${avatar()}<div><h3>${esc(state.user)}</h3><span class="muted">${esc(state.name)}</span></div></div><button data-action="profile">编辑资料</button></div></section><section class="card"><div class="setting-line"><div><h3>深色外观</h3><span class="muted">调整工作台的显示方式</span></div><button data-action="theme">${state.dark?'已开启 · 关闭':'开启'}</button></div></section><section class="card"><h3>当前为交互初版</h3><p class="muted">示例数据及你的修改仅保存在当前浏览器。尚未接入邮箱验证码、云端同步和正式账户，请先使用测试内容体验。</p><button data-action="export">导出本机数据</button></section></div>`}
function field(name,label,type='text',value='',extra=''){return `<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}
function select(name,label,options,value){return `<label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${o}</option>`).join('')}</select>`}
function area(name,label,value=''){return `<label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea>`}
function openForm(type='task',record=null){formType=type;editing=record?.id||null;const r=record||{};$('#dialog-title').textContent={task:editing?'编辑任务':'记录一件事',note:'学习记录',money:'记一笔',workout:'运动记录',idea:'记下灵感',goal:'目标与方向',review:'今日复盘',profile:'编辑个人资料'}[type];let content='';if(type==='task')content=select('recordType','记录类型',['任务','学习记录','收支','运动','灵感','复盘'],'任务')+field('title','任务名称','text',r.title,'required maxlength="160"')+select('group','所属领域',['科研','课程','课外学习','生活'],r.group)+field('date','计划日期','date',r.date||selectedDate,'required')+field('time','安排时间（可选）','time',r.time)+field('duration','预计分钟','number',r.duration||30,'min="1" max="1440" required');if(type==='note')content=field('title','标题','text',r.title,'required maxlength="160"')+select('group','所属分类',['课程','科研','课外学习'],r.group)+area('content','学习内容与笔记',r.content)+field('minutes','实际学习分钟','number',r.minutes||0,'min="0" max="1440" required');if(type==='money')content=select('kind','类型',['支出','收入'],'支出')+field('title','说明','text','','required maxlength="100"')+field('amount','金额（人民币）','number','','required min="0.01" max="99999999" step="0.01"')+select('category','分类',['餐饮','交通','学习','购物','居住','其他'],'餐饮')+field('date','日期','date',today,'required');if(type==='workout')content=select('title','运动类型',['跑步','散步','力量训练','骑行','游泳','其他'],'跑步')+field('minutes','运动分钟','number',30,'required min="1" max="1440"')+field('distance','距离（公里，可选）','number','','min="0" max="1000" step="0.01"')+field('date','日期','date',today,'required')+'<p class="muted">今日累计达到 30 分钟，将同步完成运动习惯。</p>';if(type==='idea')content=field('title','一个想法','text','','required maxlength="160"')+area('content','多写几句（可选）')+select('tag','分类',['随手记','科研灵感','生活随想','值得探索'],'随手记');if(type==='goal')content=field('title','想要靠近的目标','text',r.title,'required maxlength="160"')+select('period','时间范围',['本月','未来 3 个月','本学期','今年','长期'],r.period)+field('progress','当前进度（%）','number',r.progress||0,'required min="0" max="100"');if(type==='review')content=field('title','标题','text','今天的小结','required maxlength="160"')+area('content','收获、阻碍与明天的调整','今天的收获：\n\n想调整的事：\n\n明天的一小步：')+field('date','日期','date',today,'required');if(type==='profile')content=field('name','工作台名称','text',state.name,'required maxlength="12"')+field('user','昵称','text',state.user,'required maxlength="20"')+field('avatar','头像（可选，图片不超过 1MB）','file','','accept="image/png,image/jpeg,image/webp"');$('#fields').innerHTML=content;$('#dialog').showModal()}
document.addEventListener('change',e=>{if(e.target.name==='recordType'){let type={'任务':'task','学习记录':'note','收支':'money','运动':'workout','灵感':'idea','复盘':'review'}[e.target.value];$('#dialog').close();openForm(type)}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.page){page=d.page;filter='全部';render();window.scrollTo(0,0)}if(d.filter){filter=d.filter;render()}if(d.date){selectedDate=d.date;render()}if(d.shift){if(d.shift==='0')selectedDate=today;else{let dt=new Date(selectedDate+'T12:00:00');dt.setDate(dt.getDate()+Number(d.shift));selectedDate=dayKey(dt)}render()}if(d.task){let t=state.tasks.find(t=>t.id===d.task);t.done=!t.done;save();render()}if(d.editTask)openForm('task',state.tasks.find(t=>t.id===d.editTask));if(d.editNote)openForm('note',state.notes.find(t=>t.id===d.editNote));if(d.editGoal)openForm('goal',state.goals.find(t=>t.id===d.editGoal));if(d.habit){let k=today+':'+d.habit;if(habitDone(d.habit)&&!state.habits[k]){toast('此打卡来自关联记录，可修改或删除源记录撤销');return}state.habits[k]=!state.habits[k];save();render()}if(d.convert){let n=state.ideas.find(i=>i.id===d.convert);if(!n.taskId){n.taskId=id();state.tasks.push({id:n.taskId,title:n.title,group:'生活',date:today,time:'',duration:30,done:false,ideaId:n.id});save();render();toast('已加入今日任务，保留灵感关联')}}if(d.delete){let [key,rec]=d.delete.split(':');if(confirm('删除这条记录？相关统计将同步更新。')){state[key]=state[key].filter(x=>x.id!==rec);save();render();toast('记录已删除')}}if(d.action){if(d.action==='close')$('#dialog').close();else if(d.action==='theme'){state.dark=!state.dark;save();render()}else if(d.action==='export'){const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='有序-本机备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}else openForm(d.action==='new'?'task':d.action)}});
$('#form').addEventListener('submit',async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k in values)if(typeof values[k]==='string')values[k]=values[k].trim();if('title'in values&&!values.title){toast('请填写标题');return}if(formType==='profile'){if(!values.name||!values.user){toast('请填写名称和昵称');return}let avatar=state.avatar,file=values.avatar;if(file?.size){if(file.size>1048576||!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('请选择 1MB 以内的 PNG、JPG 或 WebP 图片');return}try{avatar=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}catch{toast('图片读取失败');return}}Object.assign(state,{name:values.name,user:values.user,avatar})}else{let key={task:'tasks',note:'notes',money:'money',workout:'workouts',idea:'ideas',goal:'goals',review:'reviews'}[formType];delete values.recordType;['minutes','amount','duration','progress','distance'].forEach(k=>{if(k in values)values[k]=Number(values[k])});if(formType==='money')values.amount=Math.round(values.amount*100)/100;if(formType==='note')values.date=today;if(editing)Object.assign(state[key].find(x=>x.id===editing),values);else state[key].unshift({id:id(),...values,...(formType==='task'?{done:false}:{})})}const ok=save();$('#dialog').close();render();if(ok)toast('已保存到当前浏览器')});
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_today_tasks',description:'读取当前工作台今天的任务，不修改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('此工具不接受参数');return {date:today,tasks:tasksFor(today).map(({id,title,done,time})=>({id,title,done,time}))}}})).catch(()=>{})}catch{}}
